fn freq(n: i32) -> i32 {
    let scale = [262, 294, 330, 349, 392, 440, 494, 523];
    let mut i: i32 = n % 8;
    if i < 0 { i = i + 8; }
    scale[i]
}

fn octave_up(f: i32) -> i32 {
    f * 2
}

fn octave_down(f: i32) -> i32 {
    f / 2
}

fn bpm_frames(bpm: i32) -> i32 {
    if bpm <= 0 { 60 } else { 3600 / bpm }
}

fn dims() -> i32 {
    (256 << 16) | 112
}

fn frame(t: i32) {
    host::display::clear(0x000000);
    host::display::draw_string(8, 8, "LIB NOTES", 0xffffff, 2);
    host::display::draw_string(8, 32, "FREQ(N) 0..7 C MAJ", 0x00ff66, 1);
    host::display::draw_string(8, 46, "OCTAVE_UP OCTAVE_DOWN", 0x00ff66, 1);
    host::display::draw_string(8, 60, "BPM_FRAMES(BPM)", 0x00ff66, 1);
    host::display::draw_number(8, 80, freq(4), 0xffff00, 1);
    host::display::draw_number(80, 80, bpm_frames(120), 0xffff00, 1);
    host::display::present();
}
